<?php
namespace App\Livewire\Admin\Users;use App\Models\Permission;use App\Models\PermissionGroup;use App\Models\User;use App\Services\AccessControlService;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\Rule;use Livewire\Component;
class Edit extends Component{public User $user;public string $name='';public string $email='';public string $role='';public bool $is_manager=false;public string $password='';public array $group_ids=[];public array $permission_ids=[];public function mount():void{$actor=auth()->user();abort_if($actor->id===$this->user->id,403);abort_unless($actor->isAdmin()||$actor->isHR()||$actor->hasPermission('users.edit'),403);abort_if(!$actor->isAdmin()&&$this->user->isAdmin(),403);$this->user->load(['permissionGroups','permissions']);foreach(['name','email','role','is_manager'] as $f)$this->$f=$this->user->$f;$this->group_ids=$this->user->permissionGroups->pluck('id')->all();$this->permission_ids=$this->user->permissions->pluck('id')->all();}public function save(AccessControlService $access){$actor=auth()->user();$roles=$actor->isAdmin()?Index::roles():collect(Index::roles())->except('admin')->all();$d=$this->validate(['name'=>['required','string','max:255'],'email'=>['required','email','max:255',Rule::unique('users')->ignore($this->user)],'role'=>['required','in:'.implode(',',array_keys($roles))],'is_manager'=>['boolean'],'password'=>['nullable','string','min:8'],'group_ids'=>['array'],'permission_ids'=>['array']]);if(!in_array($d['role'],['sales','call_center','operation','account','hr'],true))$d['is_manager']=false;$update=collect($d)->only(['name','email','role','is_manager'])->all();if(filled($d['password']))$update['password']=Hash::make($d['password']);$this->user->update($update);if($actor->isAdmin())$access->sync($this->user,$d['group_ids'],$d['permission_ids'],$actor->id);session()->flash('success','User access updated.');}public function render(){return view('livewire.admin.users.form',['heading'=>'Edit '.$this->user->name,'submitLabel'=>'Save changes','roles'=>auth()->user()->isAdmin()?Index::roles():collect(Index::roles())->except('admin')->all(),'groups'=>PermissionGroup::orderBy('display_name')->get(),'permissions'=>Permission::orderBy('resource')->orderBy('action')->get(),'editing'=>true])->layout('components.layouts.admin',['title'=>'Edit user']);}}
